-- 'my pending approvals' (PROVEN count request)

-- =============================================================================
-- 8. GOALS / OKRs
-- =============================================================================
-- PROVEN: goal id, name, description, private, start/due date, archived, completed, owners; goals list request.
-- ASSUMED: targets and everything below (PROVEN only that goals 'break down into Targets'), goal folders, rollup formula.
CREATE TABLE goal_folders (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  name text NOT NULL,
  position text COLLATE "C" NOT NULL DEFAULT 'a0',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1
);

CREATE INDEX goal_folders_ws ON goal_folders (workspace_id, position) WHERE deleted_at IS NULL;

CREATE TABLE goals (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  goal_folder_id uuid REFERENCES goal_folders(id),
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  color text,
  is_private boolean NOT NULL DEFAULT false,         -- PROVEN 'private' (workspace or private); grants belong to the access module
  start_date date,
  due_date date,
  progress_pct numeric(5,2) NOT NULL DEFAULT 0,      -- cached rollup, never typed by hand (own design page)
  progress_updated_at timestamptz,
  completed_at timestamptz,                          -- PROVEN completed flag
  archived_at timestamptz,                           -- PROVEN archived flag
  deleted_at timestamptz,
  created_by uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  CHECK (due_date IS NULL OR start_date IS NULL OR due_date >= start_date)
);

-- goals list (PROVEN request), by folder, live.
CREATE INDEX goals_list ON goals (workspace_id, goal_folder_id, created_at DESC) WHERE deleted_at IS NULL AND archived_at IS NULL;

CREATE INDEX goals_due ON goals (workspace_id, due_date) WHERE deleted_at IS NULL AND completed_at IS NULL AND due_date IS NOT NULL;

-- due-soon job
CREATE TABLE goal_owners (                           -- PROVEN owners
  goal_id uuid NOT NULL REFERENCES goals(id) ON DELETE CASCADE,
  user_id uuid NOT NULL /* id -> identity.users */,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  PRIMARY KEY (goal_id, user_id)
);

CREATE INDEX goal_owners_user ON goal_owners (workspace_id, user_id);

-- 'my goals'
CREATE TABLE goal_targets (
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  goal_id uuid NOT NULL REFERENCES goals(id) ON DELETE CASCADE,
  name text NOT NULL,
  type text NOT NULL CHECK (type IN ('number','boolean','currency','task','list')),
  start_value numeric(20,4) NOT NULL DEFAULT 0,
  current_value numeric(20,4) NOT NULL DEFAULT 0,    -- task/list types: done count, maintained by worker from change_log
  target_value numeric(20,4) NOT NULL DEFAULT 1,     -- task/list types: total count
  currency_code char(3),
  is_complete boolean NOT NULL DEFAULT false,        -- boolean type only
  weight numeric(6,2) NOT NULL DEFAULT 1 CHECK (weight > 0),   -- ASSUMED weighted average
  progress_pct numeric(5,2) NOT NULL DEFAULT 0,      -- cached per target
  position text COLLATE "C" NOT NULL DEFAULT 'a0',
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1,
  CHECK ((type = 'currency') = (currency_code IS NOT NULL))
);

CREATE INDEX goal_targets_goal ON goal_targets (workspace_id, goal_id, position) WHERE deleted_at IS NULL;

-- goal detail + rollup
CREATE TABLE goal_target_links (                     -- tasks/lists a task- or list-type target follows (many allowed)
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  target_id uuid NOT NULL REFERENCES goal_targets(id) ON DELETE CASCADE,
  task_id uuid /* id -> tasks.tasks */,
  list_id uuid /* id -> hierarchy.lists */,
  CHECK ((task_id IS NOT NULL) <> (list_id IS NOT NULL))
);

CREATE UNIQUE INDEX goal_target_links_uk ON goal_target_links (target_id, task_id, list_id) NULLS NOT DISTINCT;

-- 'which targets follow this task/list': the worker maps a task event to targets to recompute.
CREATE INDEX goal_target_links_task ON goal_target_links (workspace_id, task_id) WHERE task_id IS NOT NULL;

CREATE INDEX goal_target_links_list ON goal_target_links (workspace_id, list_id) WHERE list_id IS NOT NULL;

CREATE TABLE goal_target_updates (                   -- append-only manual progress history (for the progress chart)
  id uuid PRIMARY KEY,
  workspace_id uuid NOT NULL /* id -> access.workspaces */,
  target_id uuid NOT NULL REFERENCES goal_targets(id) ON DELETE CASCADE,
  previous_value numeric(20,4),
  new_value numeric(20,4),
  note text,
  actor_id uuid /* id -> identity.users */,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX goal_target_updates_target ON goal_target_updates (workspace_id, target_id, created_at DESC);

-- rollup: target % then goal % = weighted average. Called by the goals worker after target / linked-task events.
CREATE OR REPLACE FUNCTION goal_recompute_progress(p_goal uuid) RETURNS numeric LANGUAGE plpgsql AS $$
DECLARE v numeric;
BEGIN
  UPDATE goal_targets t SET progress_pct = CASE
      WHEN t.type = 'boolean' THEN CASE WHEN t.is_complete THEN 100 ELSE 0 END
      WHEN t.target_value = t.start_value THEN CASE WHEN t.current_value >= t.target_value THEN 100 ELSE 0 END
      ELSE greatest(0, least(100, 100 * (t.current_value - t.start_value) / (t.target_value - t.start_value))) END
  WHERE t.goal_id = p_goal AND t.deleted_at IS NULL;
  SELECT coalesce(sum(progress_pct * weight) / nullif(sum(weight), 0), 0) INTO v
    FROM goal_targets WHERE goal_id = p_goal AND deleted_at IS NULL;
  UPDATE goals SET progress_pct = v, progress_updated_at = now() WHERE id = p_goal;
  RETURN v;
END $$;
